using System;
using NaughtyAttributes;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class CorruptedAnimalCorruptionGauge : MonoBehaviour
{
	[Header("Direction")]
	[SerializeField]
	private bool purifyIncreasing;

	[Header("Fill Animation")]
	[SerializeField]
	private float fillDuration;

	[SerializeField]
	private AnimationCurve fillCurve;

	[Header("Components")]
	[SerializeField]
	private CorruptedAnimalOverCorruption corruptedAnimalOverCorruption;

	[SerializeField]
	private GameObject corruptedAnimalGo;

	[SerializeField]
	private CorruptionStats corruptionStats;

	[Header("Components Corruption Gauge")]
	[SerializeField]
	private Image gaugeFill;

	[SerializeField]
	private TextMeshProUGUI corruptionAmountText;

	[Header("Components Overcorrupted Gauge")]
	[SerializeField]
	private Image overCorruptedGaugeFill;

	[SerializeField]
	private TextMeshProUGUI overCorruptedAmountText;

	private float maxCorruption;

	private float maxOverCorruption;

	[ShowNonSerializedField]
	private bool overCorrupted;

	private bool hideCorruption;

	private bool hideOverCorruption;

	private bool infinityCorruption;

	public bool OverCorrupted => overCorrupted;

	public void Initialize(float startingCorruption, float maxOverCorruption, bool startBattleInitialize)
	{
		if (purifyIncreasing)
		{
			gaugeFill.fillOrigin = 1;
		}
		else
		{
			gaugeFill.fillOrigin = 0;
		}
		maxCorruption = startingCorruption;
		this.maxOverCorruption = maxOverCorruption;
		base.gameObject.SetActive(value: true);
		ToggleHideCorruption(hide: false);
		ToggleHideOverCorruption(hide: false);
		CheckInfinityCorruption(startingCorruption);
		if (startBattleInitialize)
		{
			gaugeFill.fillAmount = 1f;
			overCorruptedGaugeFill.fillAmount = 0f;
			UpdateCorruptionText(startingCorruption);
			UpdateOverCorruptionText(0f);
		}
		else
		{
			UpdateCorruptionGauge(startingCorruption, 0f);
		}
	}

	public void UpdateCorruptionGauge(float currentCorruption, float currentOverCorruption)
	{
		Debug.Log("currentCorruption: " + currentCorruption);
		Debug.Log("currentOverCorruption: " + currentOverCorruption);
		if (currentOverCorruption == 0f)
		{
			Debug.Log("currentOverCorruption == 0 -> TRUE");
			overCorrupted = false;
		}
		if (!hideCorruption && !infinityCorruption)
		{
			FillAnimation(gaugeFill, currentCorruption, maxCorruption);
			UpdateCorruptionText(currentCorruption);
		}
		else if (hideCorruption)
		{
			ToggleHideCorruption(hide: true);
		}
		Debug.Log("OVERCORRUPTION: currentOverCorruption " + currentOverCorruption + ", overCorrupted " + overCorrupted);
		if (!corruptionStats.IsDefeated())
		{
			Debug.Log("OVERCORRUPTION: !corruptionStats.IsDefeated() -> TRUE");
			if (currentOverCorruption == maxOverCorruption && !overCorrupted)
			{
				Debug.Log("currentOverCorruption == maxOverCorruption && !overCorrupted -> TRUE");
				overCorrupted = true;
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(corruptedAnimalOverCorruption.OverCorruptedCoroutine());
				ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
				ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnEnemyOverCorruptedOmens(corruptedAnimalGo);
				ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.EnemyOvercorruptedActiveCompanionEffectWithSource(corruptedAnimalGo);
			}
		}
		if (!hideOverCorruption)
		{
			FillAnimation(overCorruptedGaugeFill, currentOverCorruption, maxOverCorruption);
			UpdateOverCorruptionText(currentOverCorruption);
		}
		else
		{
			ToggleHideOverCorruption(hide: true);
		}
	}

	private void FillAnimation(Image gauge, float currentAmount, float maxAmount, Action afterFillAction = null)
	{
		if (base.gameObject.activeInHierarchy)
		{
			float startingFill = gauge.fillAmount;
			float targetFill = currentAmount / maxAmount;
			StartCoroutine(CoroutineUtility.CurveRoutine(fillDuration, fillCurve, delegate(float t, float v)
			{
				gauge.fillAmount = Mathf.Lerp(startingFill, targetFill, v);
			}, delegate
			{
				afterFillAction?.Invoke();
			}));
		}
	}

	private void UpdateCorruptionText(float currentCorruption)
	{
		float num = currentCorruption;
		if (purifyIncreasing)
		{
			num = maxCorruption - currentCorruption;
		}
		if (!infinityCorruption)
		{
			corruptionAmountText.SetText($"{num.ToString()} / {maxCorruption.ToString()}");
		}
	}

	private void UpdateOverCorruptionText(float currentOverCorruption)
	{
		overCorruptedAmountText.SetText($"{currentOverCorruption.ToString()}/{maxOverCorruption.ToString()}");
	}

	public void ToggleHideCorruption(bool hide)
	{
		gaugeFill.color = (hide ? Color.black : Color.white);
		hideCorruption = hide;
		if (hide)
		{
			gaugeFill.fillAmount = 1f;
			corruptionAmountText.SetText("? ? ?");
		}
	}

	public void ToggleHideOverCorruption(bool hide)
	{
		overCorruptedGaugeFill.color = (hide ? Color.black : Color.white);
		hideOverCorruption = hide;
		if (hide)
		{
			overCorruptedGaugeFill.fillAmount = 1f;
			overCorruptedAmountText.SetText("? ? ?");
		}
	}

	public void ModifyMaxOverCorruption(float newMaxOverCorruption)
	{
		maxOverCorruption = newMaxOverCorruption;
		corruptedAnimalOverCorruption.ShakeOverCorruptionAction();
		corruptedAnimalOverCorruption.ShakeOverCorruptionGauge();
	}

	private void CheckInfinityCorruption(float startingCorruption)
	{
		infinityCorruption = startingCorruption == 999f;
		if (infinityCorruption)
		{
			corruptionAmountText.SetText("∞");
			gaugeFill.fillAmount = 1f;
		}
	}

	public void ModifyMaxCorruptionAnimatedFill(float currentCorruption, float newMaxCorruption, float extraFillDuration, bool changingToInfinityCorruption)
	{
		maxCorruption = newMaxCorruption;
		float num = fillDuration + extraFillDuration;
		CoroutineUtility.ShakeRoutine(this, base.transform, num, 5f);
		CoroutineUtility.ShakeRoutine(this, corruptedAnimalGo.GetComponent<SpriteControl>().AnimationSkeletonTransform, num, 0.2f);
		if (hideCorruption)
		{
			return;
		}
		float startingFill = gaugeFill.fillAmount;
		float targetFill = currentCorruption / newMaxCorruption;
		if (changingToInfinityCorruption)
		{
			CheckInfinityCorruption(newMaxCorruption);
		}
		else
		{
			infinityCorruption = false;
		}
		StartCoroutine(CoroutineUtility.CurveRoutine(num, fillCurve, delegate(float t, float v)
		{
			if (!changingToInfinityCorruption)
			{
				UpdateCorruptionText(Mathf.RoundToInt(v * currentCorruption));
			}
			gaugeFill.fillAmount = Mathf.Lerp(startingFill, targetFill, v);
		}));
	}

	public void ModifyMaxOverCorruptionAnimatedFill(float currentOverCorruption, float newMaxOverCorruption, float extraFillDuration)
	{
		maxOverCorruption = newMaxOverCorruption;
		if (!hideOverCorruption)
		{
			float duration = fillDuration + extraFillDuration;
			float startingFill = overCorruptedGaugeFill.fillAmount;
			int targetFill = 0;
			StartCoroutine(CoroutineUtility.CurveRoutine(duration, fillCurve, delegate(float t, float v)
			{
				UpdateOverCorruptionText(Mathf.RoundToInt(v * currentOverCorruption));
				overCorruptedGaugeFill.fillAmount = Mathf.Lerp(startingFill, targetFill, v);
			}));
		}
	}
}
